  }

  private boolean expired(long ttl) {
    return clock.millis() - lastSeen > ttl;
  }

  public void touch() {
    lastSeen = clock.millis();
  }

  public boolean check(long ttl) {
    if (expired(ttl)) {
      return false;
    }
    touch();
    return true;
  }
}

